html:
{# ============================================================
   QUOTATION - BOLD / DECOR THEME
   Updated: compact quotation details and aligned item columns
   ============================================================ #}

{%- set c = frappe.db.get_value("Company", doc.company,
    ["company_name", "company_logo", "custom_print_logo",
     "custom_brand_color", "custom_default_siginture",
     "custom_print_footer", "phone_no", "email", "website"],
    as_dict=True) or {} -%}

{%- set brand = c.custom_brand_color or
    ("#6B1E64" if doc.company == "Alter Styling and Decor" else "#C8102E") -%}

{%- set logo = c.custom_print_logo or c.company_logo or
    ("/private/files/Asset 94c8d5e.png"
    if doc.company == "Alter Styling and Decor" else None) -%}

{# Light brand tint #}
{%- set hx = "0123456789abcdef" -%}
{%- set b = brand|lower -%}

{%- if b|length == 7 and b.startswith("#") and
    (b[1:]|select("in", hx)|list|length == 6) -%}
    {%- set tint = "rgba(%d, %d, %d, 0.10)"|format(
        hx.index(b[1])*16 + hx.index(b[2]),
        hx.index(b[3])*16 + hx.index(b[4]),
        hx.index(b[5])*16 + hx.index(b[6])
    ) -%}
{%- else -%}
    {%- set tint = "#eef0f4" -%}
{%- endif -%}

{# Dynamic signature #}
{%- set sig = None -%}

{%- if pctx.show_signature and doc.get("print_signature") -%}
    {%- set sig = frappe.db.get_value(
        "Signature", doc.print_signature,
        ["signature_name", "position", "attach"], as_dict=True
    ) -%}
{%- endif -%}

{%- if not sig and c.get("custom_default_siginture") -%}
    {%- set sig = frappe.db.get_value(
        "Signature", c.custom_default_siginture,
        ["signature_name", "position", "attach"], as_dict=True
    ) -%}
{%- endif -%}

{%- if not sig -%}
    {%- set sig = frappe.db.get_value(
        "Signature", {"signature_name": "Hilina Mulatu"},
        ["signature_name", "position", "attach"], as_dict=True
    ) -%}
{%- endif -%}

{%- set sign_img = sig.attach if sig else None -%}

{# Print context #}
{%- set pctx = doc._print_context or
    (get_print_context(doc) if get_print_context is defined else None) -%}

{%- if not pctx -%}

    {%- set items_list = doc.items or [] -%}
    {%- set has_days = False -%}
    {%- set has_pages = False -%}

    {%- for r in items_list -%}
        {%- if (r.number_of_days or 0)|float > 0 -%}
            {%- set has_days = True -%}
        {%- endif -%}

        {%- if (r.number_of_pages or 0)|float > 0 -%}
            {%- set has_pages = True -%}
        {%- endif -%}
    {%- endfor -%}

    {%- set show_sub = doc.print_show_section_subtotals
        if doc.print_show_section_subtotals is not none else True -%}

    {%- set show_days = doc.print_show_number_of_days
        if doc.print_show_number_of_days else has_days -%}

    {%- set show_pages = doc.print_show_number_of_pages
        if doc.print_show_number_of_pages else has_pages -%}

    {%- set hide_qty = doc.print_hide_qty
        if doc.print_hide_qty else False -%}

    {%- set without_vat = doc.print_without_vat
        if doc.print_without_vat else False -%}

    {%- set cols = 3 -%}

    {%- if not hide_qty -%}
        {%- set cols = cols + 1 -%}
    {%- endif -%}

    {%- if show_days -%}
        {%- set cols = cols + 1 -%}
    {%- endif -%}

    {%- if show_pages -%}
        {%- set cols = cols + 1 -%}
    {%- endif -%}

    {%- set pctx = {
        'show_subtotals': show_sub,
        'show_days': show_days,
        'show_pages': show_pages,
        'hide_qty': hide_qty,
        'without_vat': without_vat,
        'total_columns': cols,
        'title_colspan': cols,
        'subtotal_label_colspan': cols - 1,
        'show_signature': True
    } -%}

{%- endif -%}

{# Exact rendered column count based on visible headers #}
{%- set actual_cols = 3
    + (0 if pctx.hide_qty else 1)
    + (1 if pctx.show_days else 0)
    + (1 if pctx.show_pages else 0) -%}


<style>

    /* =====================================
       GENERAL
    ===================================== */

    .bd_wrap {
        width: 100%;
        max-width: 100%;
        box-sizing: border-box;
        color: #111827;
        font-size: 13px;
    }

    .bd_wrap * {
        box-sizing: border-box;
    }

    .bd_accent {
        color: {{ brand }} !important;
    }


    /* =====================================
       HEADER
    ===================================== */

    .bd_wrap .bd_head {
        width: 100%;
        background: {{ brand }};
        border-collapse: separate;
        border-spacing: 0;
        border-radius: 15px;
        overflow: hidden;
        color: white;
        margin-bottom: 25px;
    }

    .bd_head td {
        padding: 22px 30px;
        vertical-align: middle;
    }

    .bd_head_l {
        width: 65%;
    }

    .bd_head_r {
        width: 35%;
        text-align: right;
    }

    .bd_title {
        font-size: 36px;
        font-weight: 900;
        text-transform: uppercase;
        letter-spacing: 3px;
        line-height: 1.2;
        color: white;
    }

    .bd_sub {
        color: white;
        font-size: 13px;
        margin-top: 8px;
    }

    .bd_pill {
        display: inline-block;
        border: 1px solid white;
        border-radius: 20px;
        padding: 3px 14px;
        margin-left: 10px;
        font-size: 10px;
        font-weight: bold;
    }

    .bd_logo {
        display: inline-block;
        background: white;
        padding: 10px 18px;
        border-radius: 12px;
    }

    .bd_logo img {
        max-width: 180px;
        max-height: 75px;
        object-fit: contain;
    }

    .bd_company {
        color: white;
        font-size: 18px;
        font-weight: bold;
    }


    /* =====================================
       CUSTOMER / QUOTATION DETAILS
    ===================================== */

    .bd_info {
        width: 100% !important;
        border-collapse: collapse;
        table-layout: fixed;
        margin: 0 0 25px;
    }

    .bd_info td {
        vertical-align: top;
        padding: 5px 0;
    }

    .bd_info_l {
        width: 65%;
        text-align: left;
        padding-right: 20px !important;
        line-height: 1.65;
    }

    .bd_info_r {
        width: 35%;
        text-align: right;
        vertical-align: top;
    }

    .bd_label {
        font-size: 12px;
        font-weight: 900;
        text-transform: uppercase;
        letter-spacing: 2px;
        margin-bottom: 12px;
    }

    .bd_name {
        font-size: 16px;
        font-weight: bold;
    }

    .bd_addr {
        margin-top: 5px;
    }


    /* Compact Date / Valid Till table */

    .bd_wrap .bd_kv {
        width: auto !important;
        display: inline-table !important;
        margin-left: auto !important;
        margin-right: 0 !important;
        border-collapse: collapse !important;
        border-spacing: 0 !important;
        table-layout: auto !important;
    }

    .bd_wrap .bd_kv td {
        width: auto !important;
        padding: 2px 0 !important;
        line-height: 1.4;
        border: none !important;
        vertical-align: middle;
        white-space: nowrap;
    }

    .bd_wrap .bd_kv td:first-child {
        text-align: left !important;
        padding-right: 16px !important;
    }

    .bd_wrap .bd_kv td:last-child {
        text-align: right !important;
        font-weight: bold;
    }


    /* =====================================
       DESCRIPTION
    ===================================== */

    .bd_desc {
        margin: 20px 0;
        padding: 12px 0;
        line-height: 1.6;
    }


    /* =====================================
       ITEMS TABLE
       All columns use one fixed table grid.
    ===================================== */

    .bd_items {
        width: 100% !important;
        max-width: 100% !important;
        table-layout: fixed !important;
        border-collapse: collapse !important;
        border-spacing: 0 !important;
        margin: 15px 0 0;
        font-size: 13px;
    }

    .bd_items th,
    .bd_items td {
        box-sizing: border-box !important;
        overflow-wrap: break-word;
        vertical-align: middle;
    }

    .bd_items th {
        background: {{ brand }} !important;
        color: white !important;
        padding: 13px 10px !important;
        font-weight: 900;
        font-size: 12px;
        text-transform: uppercase;
        letter-spacing: 0.7px;
        line-height: 1.5;
        border: none !important;
    }

    /* Alignment */

    .bd_l {
        text-align: left !important;
    }

    .bd_r {
        text-align: right !important;
    }

    .bd_c {
        text-align: center !important;
    }

    .bd_bold {
        font-weight: bold !important;
    }

    /* Item rows */

    .bd_row td {
        background: #f7f8fa;
        padding: 17px 10px !important;
        border-bottom: 1px solid #e8e8ec;
        line-height: 1.5;
    }

    .bd_item {
        font-size: 15px;
        font-weight: bold;
        color: #111827;
        margin-bottom: 3px;
    }

    .bd_item_desc {
        font-size: 12px;
        color: #475569;
        line-height: 1.5;
    }

    .bd_uom {
        font-size: 12px;
        color: #475569;
        margin-top: 3px;
    }


    /* Section rows: same width as the item table */

    .bd_items .bd_section td {
        background: {{ tint }} !important;
        color: {{ brand }} !important;
        padding: 13px 18px !important;
        font-weight: bold;
        font-size: 14px;
        text-align: left !important;
        border: none !important;
        line-height: 1.4;
    }


    /* Section subtotal rows */

    .bd_items .bd_subtotal_row td {
        background: #f7f8fa;
        padding: 13px 10px !important;
        border-top: 1px solid #e2e4e9;
        border-bottom: 1px solid #e2e4e9;
        white-space: nowrap;
    }


    /* =====================================
       TOTALS
    ===================================== */

    .bd_sum {
        width: 100%;
        border-collapse: collapse;
        margin-top: 12px;
        font-size: 14px;
    }

    .bd_sum td {
        padding: 10px 14px;
        border-bottom: 1px solid #e8e8ec;
    }

    .bd_sum td:first-child {
        text-align: left;
    }

    .bd_sum td:last-child {
        text-align: right;
        font-weight: bold;
        white-space: nowrap;
    }

    .bd_sum .bd_grand td {
        color: {{ brand }};
        border-top: 2px solid {{ brand }};
        border-bottom: 2px solid {{ brand }};
        font-size: 16px;
        font-weight: 900;
        padding-top: 14px;
        padding-bottom: 14px;
    }

    .bd_words {
        margin-top: 15px;
        font-size: 12px;
        font-style: italic;
    }


    /* =====================================
       TERMS / SIGNATURE
    ===================================== */

    .bd_bottom {
        width: 100%;
        border-collapse: collapse;
        margin-top: 30px;
    }

    .bd_bottom td {
        vertical-align: bottom;
        padding: 12px 0;
    }

    .bd_bottom_l {
        width: 65%;
        padding-right: 20px !important;
    }

    .bd_bottom_r {
        width: 35%;
        text-align: center;
    }

    .bd_terms {
        font-size: 12px;
        line-height: 1.6;
    }

    .bd_thanks {
        color: {{ brand }};
        font-size: 15px;
        font-weight: bold;
        margin-top: 20px;
    }

    .bd_sign_wrap {
        text-align: center;
    }

    .bd_sign img {
        max-width: 150px;
        max-height: 75px;
        object-fit: contain;
    }

    .bd_sign_name {
        font-weight: bold;
        margin-top: 5px;
    }

    .bd_sign_pos {
        font-size: 11px;
        color: #64748b;
    }


    /* =====================================
       FOOTER
    ===================================== */

    .pbd_footer {
        text-align: center;
        padding-top: 10px;
        font-size: 10px;
        line-height: 1.6;
    }

    .pbd_footer_title {
        font-weight: bold;
        font-size: 12px;
    }


    /* =====================================
       PRINT / PDF
    ===================================== */

    @media print {

        .bd_items {
            width: 100% !important;
            table-layout: fixed !important;
        }

        .bd_items th,
        .bd_items td {
            box-sizing: border-box !important;
        }

        .bd_info,
        .bd_items,
        .bd_sum,
        .bd_bottom {
            page-break-inside: auto;
        }

        .bd_row,
        .bd_section,
        .bd_subtotal_row {
            page-break-inside: avoid;
        }

    }

</style>


<div class="bd_wrap">

    <!-- HEADER -->

    <div class="bd_card">

        <table class="bd_head">
            <tr>

                <td class="bd_head_l">

                    <div class="bd_title">
                        {{ _("Quotation") }}
                    </div>

                    <div class="bd_sub">

                        {{ doc.name }}

                        {% if doc.docstatus == 0 %}
                            <span class="bd_pill">DRAFT</span>
                        {% elif doc.docstatus == 2 %}
                            <span class="bd_pill">CANCELLED</span>
                        {% endif %}

                    </div>

                </td>

                <td class="bd_head_r">

                    {% if logo %}

                        <span class="bd_logo">
                            <img src="{{ logo }}"
                                 alt="{{ c.company_name or doc.company }}">
                        </span>

                    {% else %}

                        <span class="bd_company">
                            {{ c.company_name or doc.company }}
                        </span>

                    {% endif %}

                </td>

            </tr>
        </table>

    </div>


    <!-- CUSTOMER AND QUOTATION DETAILS -->

    <table class="bd_info">

        <tr>

            <td class="bd_info_l">

                <div class="bd_label bd_accent">
                    {{ _("Quotation To") }}
                </div>

                <div class="bd_name">
                    {{ doc.customer_name or doc.party_name }}
                </div>

                {% if doc.get("contact_display")
                    and doc.contact_display != doc.customer_name %}
                    <div>{{ doc.contact_display }}</div>
                {% endif %}

                {% if doc.get("contact_mobile") %}
                    <div>
                        {{ _("Phone") }}: {{ doc.contact_mobile }}
                    </div>
                {% endif %}

                {% if doc.get("contact_email") %}
                    <div>
                        {{ _("Email") }}: {{ doc.contact_email }}
                    </div>
                {% endif %}

                {% if doc.get("address_display") %}
                    <div class="bd_addr">
                        {{ doc.address_display }}
                    </div>
                {% endif %}

            </td>


            <td class="bd_info_r">

                <table class="bd_kv">

                    {% if doc.transaction_date %}
                        <tr>
                            <td>{{ _("Date") }}</td>
                            <td>
                                {{ doc.get_formatted("transaction_date") }}
                            </td>
                        </tr>
                    {% endif %}

                    {% if doc.get("valid_till") %}
                        <tr>
                            <td>{{ _("Valid Till") }}</td>
                            <td>
                                {{ doc.get_formatted("valid_till") }}
                            </td>
                        </tr>
                    {% endif %}

                    {% if doc.get("order_type")
                        and doc.order_type != "Sales" %}
                        <tr>
                            <td>{{ _("Type") }}</td>
                            <td>{{ doc.order_type }}</td>
                        </tr>
                    {% endif %}

                </table>

            </td>

        </tr>

    </table>


    <!-- SERVICE DESCRIPTION / EVENT DETAILS -->

    {% if doc.get("desc") or doc.get("event_date")
        or doc.get("event_location") %}

        <div class="bd_desc">

            {% if doc.get("event_date") or doc.get("event_location") %}

                <div style="margin-bottom: 8px;">

                    {% if doc.get("event_date") %}
                        <span style="margin-right: 18px;">
                            <b>Event Date:</b>
                            {{ doc.get_formatted("event_date") }}
                        </span>
                    {% endif %}

                    {% if doc.get("event_location") %}
                        <span>
                            <b>Location:</b>
                            {{ doc.event_location }}
                        </span>
                    {% endif %}

                </div>

            {% endif %}

            {% if doc.get("desc") %}

                <div class="bd_label bd_accent">
                    {{ _("Service Description") }}
                </div>

                {{ doc.desc }}

            {% endif %}

        </div>

    {% endif %}


    <!-- ITEMS TABLE -->

    <table class="bd_items">

        <colgroup>
            <col style="width: 30%;">
            <col style="width: 16%;">
            {% if not pctx.hide_qty %}
                <col style="width: 10%;">
            {% endif %}
            {% if pctx.show_days %}
                <col style="width: 14%;">
            {% endif %}
            {% if pctx.show_pages %}
                <col style="width: 9%;">
            {% endif %}
            <col style="width: 21%;">
        </colgroup>

        <thead>

            <tr>

                <th class="bd_l">
                    {{ _("Item Description") }}
                </th>

                <th class="bd_r bd_w_price">
                    {{ _("Unit Price") }} ({{ doc.currency }})
                </th>

                {% if not pctx.hide_qty %}
                    <th class="bd_c bd_w_qty">
                        {{ _("Qty") }}
                    </th>
                {% endif %}

                {% if pctx.show_days %}
                    <th class="bd_r bd_w_days">
                        {{ _("No. of Days") }}
                    </th>
                {% endif %}

                {% if pctx.show_pages %}
                    <th class="bd_c bd_w_pages">
                        {{ _("Pages") }}
                    </th>
                {% endif %}

                <th class="bd_r bd_w_total">
                    {{ _("Total") }} ({{ doc.currency }})
                </th>

            </tr>

        </thead>


        <tbody>

            {% for row in doc.items %}

                {% if row.get("is_section")
                    or row.item_name == "Separator"
                    or row.item_code == "Separator" %}

                    <!-- SECTION -->

                    <tr class="bd_section">

                        <td colspan="{{ actual_cols }}">
                            {{ row.get("section_title")
                                or row.description
                                or row.item_name }}
                        </td>

                    </tr>


                {% elif row.is_section_subtotal %}

                    <!-- SECTION SUBTOTAL -->

                    <tr class="bd_subtotal_row">

                        <td colspan="{{ actual_cols - 1 }}"
                            class="bd_r bd_bold"
                            style="padding-right: 14px !important;">
                            Subtotal ({{ row.section_title or "" }}):
                        </td>

                        <td class="bd_r bd_bold">
                            {{ "{:,.2f}".format(row.amount or 0) }}
                        </td>

                    </tr>


                {% else %}

                    <!-- NORMAL ITEM -->

                    <tr class="bd_row">

                        <td class="bd_l">

                            <div class="bd_item">
                                {{ row.item_name or row.item_code }}
                            </div>

                            {% if row.description
                                and row.description|striptags|trim
                                != (row.item_name or "")|trim %}

                                <div class="bd_item_desc">
                                    {{ row.description }}
                                </div>

                            {% endif %}

                        </td>


                        <td class="bd_r">

                            {{ "{:,.2f}".format(row.rate or 0) }}

                        </td>


                        {% if not pctx.hide_qty %}

                            <td class="bd_c">

                                {{ row.get_formatted("qty", doc)
                                    if row.get("qty") is not none
                                    else row.get_formatted("quantity", doc) }}

                                {% if row.uom and row.uom != "Nos" %}
                                    <div class="bd_uom">
                                        {{ row.uom }}
                                    </div>
                                {% endif %}

                            </td>

                        {% endif %}


                        {% if pctx.show_days %}

                            <td class="bd_r">

                                {{ "{:,.2f}".format(
                                    row.get("number_of_days") or 0
                                ) }}

                            </td>

                        {% endif %}


                        {% if pctx.show_pages %}

                            <td class="bd_c">

                                {{ "{:,.0f}".format(
                                    row.get("number_of_pages") or 0
                                ) }}

                            </td>

                        {% endif %}


                        <td class="bd_r bd_bold">

                            {{ "{:,.2f}".format(row.amount or 0) }}

                        </td>

                    </tr>

                {% endif %}

            {% endfor %}

        </tbody>

    </table>


    <!-- TOTALS -->

    <table class="bd_sum">

        <tr>
            <td>{{ _("Sub-Total") }}</td>
            <td>{{ doc.get_formatted("total") }}</td>
        </tr>


        {% if doc.discount_amount %}

            <tr>

                <td>

                    {{ _("Discount") }}

                    {% if doc.additional_discount_percentage %}
                        ({{ doc.additional_discount_percentage }}%)
                    {% endif %}

                </td>

                <td>
                    -{{ doc.get_formatted("discount_amount") }}
                </td>

            </tr>


            {% if doc.net_total and doc.net_total != doc.total %}

                <tr>
                    <td>{{ _("Net Total") }}</td>
                    <td>{{ doc.get_formatted("net_total") }}</td>
                </tr>

            {% endif %}

        {% endif %}


        {% if not pctx.without_vat %}

            {% for tax in doc.taxes %}

                {% if tax.tax_amount %}

                    <tr>

                        <td>

                            {{ tax.description }}

                            {% if tax.rate %}
                                ({{ tax.rate }}%)
                            {% endif %}

                        </td>

                        <td>
                            {{ tax.get_formatted("tax_amount") }}
                        </td>

                    </tr>

                {% endif %}

            {% endfor %}


            <tr class="bd_grand">

                <td>{{ _("Grand Total") }}:</td>

                <td>
                    {{ doc.get_formatted("grand_total") }}
                </td>

            </tr>

        {% else %}

            <tr class="bd_grand">

                <td>{{ _("Grand Total (excl. VAT)") }}:</td>

                <td>
                    {{ doc.get_formatted("net_total")
                        or doc.get_formatted("total") }}
                </td>

            </tr>

        {% endif %}

    </table>


    {% if doc.get("in_words") %}

        <div class="bd_words">
            {{ doc.in_words }}
        </div>

    {% endif %}


    <!-- TERMS AND SIGNATURE -->

    <table class="bd_bottom">

        <tr>

            <td class="bd_bottom_l">

                {% if pctx.show_terms and doc.terms %}

                    <div class="bd_label bd_accent">
                        {{ _("Terms & Conditions") }}
                    </div>

                    <div class="bd_terms">
                        {{ doc.terms }}
                    </div>

                {% endif %}


                <div class="bd_thanks">
                    {{ _("Thank You For Your Business") }}
                </div>

            </td>


            <td class="bd_bottom_r">

                {% if sign_img or sig %}

                    <div class="bd_sign_wrap">

                        {% if sign_img %}

                            <div class="bd_sign">
                                <img src="{{ sign_img }}" alt="">
                            </div>

                        {% endif %}


                        {% if sig %}

                            <div class="bd_sign_text">

                                <div class="bd_sign_name">
                                    {{ sig.signature_name }}
                                </div>

                                {% if sig.position %}

                                    <div class="bd_sign_pos">
                                        {{ sig.position }}
                                    </div>

                                {% endif %}

                            </div>

                        {% endif %}

                    </div>

                {% endif %}

            </td>

        </tr>

    </table>

</div>


<!-- COMPANY FOOTER -->

<div id="footer-html" class="visible-pdf">

    <div class="pbd_footer"
         style="border-top: 3px solid {{ brand }};">

        <b class="pbd_footer_title"
           style="color: {{ brand }};">

            {{ c.company_name or doc.company }}

        </b>


        {% if c.custom_print_footer %}

            {% for line in c.custom_print_footer.split("\n")
                if line.strip() %}

                <br>
                {{ line.strip() }}

            {% endfor %}


        {% else %}

            {% if c.phone_no or c.email %}

                <br>

                {% if c.phone_no %}
                    <b>Phone:</b> {{ c.phone_no }}
                {% endif %}

                {% if c.email %}
                    <b>Email:</b> {{ c.email }}
                {% endif %}

            {% endif %}

        {% endif %}

    </div>

</div>

