@import url("https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap");

/* ==========================================================================
   SIGNATURE / STAMP PICTURE
   ========================================================================== */

.bd_wrap .bd_sign {
  width: 260px;
  height: 175px;
  overflow: hidden;
  margin-left: auto;
}

.bd_wrap .bd_sign img,
body:last-child .print-format .bd_wrap .bd_sign img {
  width: 443px !important;
  max-width: none !important;
  max-height: none !important;
  margin: -85px 0 0 -95px;
}

/* Hide text because the signature image already contains the name */
.bd_wrap .bd_sign_text {
  display: none;
}

/* ==========================================================================
   GENERAL STYLING
   ========================================================================== */

.bd_wrap,
.bd_wrap * {
  -webkit-box-sizing: border-box;
  box-sizing: border-box;
}

.bd_wrap {
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  line-height: 1.5;
  color: #1f2733;
}

.bd_wrap table {
  width: 100%;
  border-collapse: collapse;
  border-spacing: 0;
}

.bd_wrap td,
.bd_wrap th {
  padding: 0;
  border: 0;
  vertical-align: top;
}

.bd_wrap img {
  border: 0;
  max-width: 100%;
  height: auto;
}

.bd_wrap div,
.bd_wrap p {
  margin: 0;
}

/* ==========================================================================
   HEADER
   ========================================================================== */

.bd_wrap .bd_card {
  border-radius: 14px;
  overflow: hidden;
  margin-bottom: 26px;
  border: 1px solid #e6e8ee;
}

.bd_wrap .bd_head td {
  padding: 26px 30px;
  vertical-align: middle;
}

.bd_wrap .bd_head_r {
  text-align: right;
}

.bd_wrap .bd_title {
  font-size: 38px;
  font-weight: 800;
  letter-spacing: 3px;
  line-height: 1.1;
  color: #fff;
  text-transform: uppercase;
}

.bd_wrap .bd_sub {
  margin-top: 8px;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.5px;
  color: #fff;
}

.bd_wrap .bd_pill {
  display: inline-block;
  margin-left: 8px;
  padding: 1px 9px;
  border: 1px solid rgba(255, 255, 255, 0.8);
  border-radius: 20px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1.5px;
  color: #fff;
}

.bd_wrap .bd_logo {
  display: inline-block;
  padding: 10px 16px;
  border-radius: 10px;
  background: #fff;
}

.bd_wrap .bd_logo img,
body:last-child .print-format .bd_wrap .bd_logo img {
  display: block;
  width: auto !important;
  max-height: 54px;
  max-width: 190px;
}

.bd_wrap .bd_company {
  font-size: 20px;
  font-weight: 700;
  color: #fff;
}

/* ==========================================================================
   CUSTOMER AND QUOTATION DETAILS
   ========================================================================== */

.bd_wrap .bd_info {
  margin-bottom: 26px;
}

.bd_wrap .bd_info_l {
  width: 55%;
  padding-right: 20px;
}

.bd_wrap .bd_info_r {
  width: 45%;
}

.bd_wrap .bd_label {
  margin-bottom: 7px;
  font-size: 11.5px;
  font-weight: 800;
  letter-spacing: 1.4px;
  text-transform: uppercase;
}

.bd_wrap .bd_name {
  font-size: 15px;
  font-weight: 700;
  color: #111827;
  margin-bottom: 2px;
}

.bd_wrap .bd_addr {
  margin-top: 3px;
  color: #2f3846;
}

/* Date and Valid Till */
.bd_wrap .bd_kv {
  width: 100%;
  border-collapse: collapse;
}

.bd_wrap .bd_kv td {
  padding: 3px 0;
  line-height: 1.5;
  vertical-align: middle;
}

.bd_wrap .bd_kv tr:first-child td {
  padding-top: 0;
}

.bd_wrap .bd_kv td:first-child {
  color: #4b5563;
  padding-right: 14px;
  white-space: nowrap;
}

.bd_wrap .bd_kv td:last-child {
  text-align: right;
  font-weight: 600;
  color: #111827;
  white-space: nowrap;
}

/* ==========================================================================
   SERVICE DESCRIPTION
   ========================================================================== */

.bd_wrap .bd_desc {
  margin-bottom: 22px;
  padding: 14px 16px;
  border: 1px solid #e6e8ee;
  border-radius: 10px;
}

/* ==========================================================================
   ITEMS TABLE
   ========================================================================== */

.bd_wrap .bd_items {
  margin-bottom: 4px;
}

.bd_wrap .bd_items th {
  padding: 11px 14px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  color: #fff;
  vertical-align: middle;
}

.bd_wrap .bd_items th:first-child {
  border-radius: 8px 0 0 8px;
}

.bd_wrap .bd_items th:last-child {
  border-radius: 0 8px 8px 0;
}

.bd_wrap .bd_items td {
  padding: 12px 14px;
  font-size: 13.5px;
  vertical-align: middle;
  border-bottom: 1px solid #eef0f4;
}

.bd_wrap .bd_row:nth-child(even) td {
  background: #f7f8fa;
}

.bd_wrap .bd_items tr {
  page-break-inside: avoid;
}

.bd_wrap .bd_section td {
  padding: 10px 14px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.4px;
  border-bottom: 0;
}

.bd_wrap .bd_subtotal_row td {
  padding: 9px 14px;
  font-size: 13px;
  font-weight: 700;
  color: #111827;
  background: #f7f8fa;
  border-top: 1px dashed #d1d5db;
  border-bottom: 2px solid #e5e7eb;
}

.bd_wrap .bd_l {
  text-align: left;
}

.bd_wrap .bd_r {
  text-align: right;
}

.bd_wrap .bd_c {
  text-align: center;
}

.bd_wrap .bd_bold {
  font-weight: 700;
  color: #111827;
}

.bd_wrap .bd_w_price {
  width: 18%;
}

.bd_wrap .bd_w_qty {
  width: 10%;
}

.bd_wrap .bd_w_days {
  width: 12%;
}

.bd_wrap .bd_w_pages {
  width: 10%;
}

.bd_wrap .bd_w_total {
  width: 18%;
}

.bd_wrap .bd_item {
  font-size: 14px;
  font-weight: 700;
  color: #111827;
}

.bd_wrap .bd_item_desc {
  margin-top: 2px;
  font-size: 12px;
  color: #4b5563;
}

.bd_wrap .bd_uom {
  font-size: 11.5px;
  color: #4b5563;
}

/* ==========================================================================
   TOTALS
   ========================================================================== */

.bd_wrap .bd_sum {
  margin: 6px 0 4px;
}

.bd_wrap .bd_sum td {
  padding: 11px 14px;
  font-size: 13px;
  border-bottom: 1px solid #e3e6ec;
  color: #1f2733;
}

.bd_wrap .bd_sum td:last-child {
  text-align: right;
  font-weight: 600;
  color: #111827;
}

.bd_wrap .bd_sum .bd_grand td {
  padding-top: 14px;
  padding-bottom: 14px;
  font-size: 18px;
  font-weight: 800;
  border-bottom: 0;
}

.bd_wrap .bd_words {
  margin: 0 14px;
  font-size: 11.5px;
  font-style: italic;
  color: #2f3846;
}

/* ==========================================================================
   TERMS AND CONDITIONS / SIGNATURE
   ========================================================================== */

.bd_wrap .bd_bottom {
  margin-top: 30px;
  page-break-inside: avoid;
}

.bd_wrap .bd_bottom_l {
  width: 58%;
  padding-right: 24px;
}

.bd_wrap .bd_bottom_r {
  width: 42%;
  text-align: right;
}

.bd_wrap .bd_bottom_l .bd_label {
  color: inherit;
  margin-bottom: 7px;
  font-size: 11.5px;
  font-weight: 800;
  letter-spacing: 1.4px;
  text-transform: uppercase;
}

.bd_wrap .bd_terms {
  font-size: 11.5px;
  line-height: 1.6;
  color: #2f3846;
}

.bd_wrap .bd_thanks {
  margin-top: 16px;
  font-size: 15px;
  font-weight: 800;
}

.bd_wrap .bd_sign_name {
  font-size: 15px;
  font-weight: 700;
  color: #111827;
}

.bd_wrap .bd_sign_pos {
  font-size: 10.5px;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: #4b5563;
}

/* ==========================================================================
   COMPANY FOOTER
   ========================================================================== */

.pbd_footer {
  margin: 0 10px;
  padding: 11px 16px 12px;
  border-radius: 10px;
  background: #f3f4f7;
  color: #111827;
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  line-height: 1.5em;
  text-align: center;
}

.pbd_footer_title {
  font-size: 15px;
  font-weight: 700;
}
